{
  "duration_weeks": 12,
  "phases": [
    {
      "name": "Foundations & Movement Prep",
      "weeks": 4,
      "focus": "Restore balanced strength, mobility, and low-impact movement patterns while protecting the repaired right medial meniscus."
    },
    {
      "name": "Strength Build (Low-Impact)",
      "weeks": 5,
      "focus": "Progress overall and unilateral strength with controlled ranges, increased load, and emphasis on joint control without deep knee flexion or impact."
    },
    {
      "name": "Ski-Specific Strength & Transfer",
      "weeks": 3,
      "focus": "Develop sport-specific strength, endurance and stability for skiing with low-impact, loaded positional work and neural preparation for return to ski tasks."
    }
  ],
  "weekly_template": {
    "days_per_week": 4,
    "day_types": [
      "Lower (low-impact, bilateral emphasis)",
      "Upper (push/pull strength)",
      "Unilateral & Core (single-leg control, hip/ankle strength)",
      "Full-body (power/conditioning low-impact, ski-specific)"
    ]
  },
  "non_negotiables": [
    "No jumping",
    "No deep knee flexion under load",
    "Low-impact only as cleared by surgeon",
    "Progress only within pain-free ranges and patient-reported tolerance",
    "Use full gym equipment but choose variations that avoid deep knee bend (e.g., box/quarter/partial range, belt squats, split squats limited ROM)",
    "Monitor swelling or increased knee effusion; back off if symptoms increase"
  ]
}
